function bookingEnd(b){if(b.end_slot)return b.end_slot.slice(0,5);return clockMinute(timeMinute(b.slot)+120)}
function timeMinute(v){const [h,m]=String(v).split(':').map(Number);return h*60+m}
function clockMinute(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function photoInput(id,url){return ht`<label>RASM YUKLASH<input id="${id}" type="file" accept="image/jpeg,image/png,image/webp" data-photo-input></label><small>JPG, PNG yoki WebP. Telefon yoki kompyuterdan tanlang.</small><img id="${id}Preview" class="photo-preview" ${url?ht`src="${esc(url)}"`:'hidden'} alt="Tanlangan rasm">`}
