// Start plan: a plain text list of tables. Business/Premium: the 3D hall (2D plan stays as the no-WebGL fallback).
// live: tables a camera sees in use right now (only for today, within 2 hours of the chosen start).
function tableList(list,conflict,bookingsFor,selected,live=new Map()){return ht`<ul class="table-list">${list.map(tb=>{const l=live.get(tb.number),state=conflict(tb)?'busy':l?.status==='occupied'?'live':l?.status==='cleaning'?'cleaning':bookingsFor(tb).length?'reserved':'free';return ht`<li><button type="button" class="quiet ${selected?.id===tb.id?'active':''}" data-table="${esc(tb.id)}" aria-pressed="${selected?.id===tb.id}"><b>${esc(tb.number)}-stol</b> · ${esc(tb.seats)} kishi · ${state==='busy'?t('tanlangan vaqtda band'):state==='live'?'🔴 '+t(t('hozir band'))+' · '+sinceLabel(l.since):state==='cleaning'?'🟡 '+t(t('tozalanmoqda, tez orada bo‘shaydi')):state==='reserved'?t('boshqa vaqtga bron bor'):l?.status==='free'?'🟢 '+t(t('hozir bo‘sh')):t('bo‘sh')}</button></li>`}).join('')}</ul>`}
// What the restaurant's camera / staff see right now: number -> {status, since}. Only shown for
// today and when the chosen start is within 2 hours, since it says nothing about later visits.
function liveState(d){const local=new Date(Date.now()+5*3600000),today=local.toISOString().slice(0,10),out=new Map();if($('#planDate')?.value!==today)return out;const now=local.getUTCHours()*60+local.getUTCMinutes();if(timeMinute($('#planStart').value)-now>120)return out;for(const l of d.live||[])if(['occupied','cleaning','free'].includes(l.status))out.set(l.table_number,{status:l.status,since:l.since||l.updated_at});return out}
// "since 14:05" in each language's word order.
function sinceLabel(v){const time=liveSince(v),lang=RF_I18N.lang;return lang==='ru'?'с '+time:lang==='en'?'since '+time:time+t(' dan beri')}
function liveSince(v){const d=new Date(v);return isNaN(d)?'':d.toLocaleTimeString(RF_I18N.locale(),{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tashkent'})}
function showHall3D(host,d,floor,list,selected,conflict,onSelect){if(!window.RF3DLoad)return;const viewport=host.querySelector('#floorViewport');let target=host.querySelector('[data-hall-3d]');if(!target){target=document.createElement('div');target.setAttribute('data-hall-3d','');viewport.before(target)}const live=liveState(d),states={};for(const t of list){const l=live.get(t.number);states[t.number]=conflict(t)?'booked':l&&l.status!=='free'?l.status:'free'}window.RF3DLoad().then(api=>{if(!target.isConnected)return;if(api.hall.mount(target,{tables:d.tables,width:d.width,length:d.length,floor,states,selected:selected?.number??null,onSelect,lang:document.documentElement.lang})){viewport.hidden=true;host.querySelector('.swipe-hint')?.setAttribute('hidden','')}}).catch(()=>{})}
function hallStyle(d){const w=Number(d.width)||12,l=Number(d.length)||8;return ht`--hall-ratio:${w}/${l};--hall-min-width:${Math.max(640,Math.round(360*w/l))}px;`}
function closeBookingRoom(){window.RFBookingMeals?.close();if(typeof demoDispose==='function')demoDispose();clearInterval(bookingPoll);bookingPoll=null;const dialog=document.getElementById('bookingRoom');if(dialog){dialog.close();dialog.remove()}document.body.classList.remove('booking-open')}
window.addEventListener('hashchange',closeBookingRoom);
async function bookingPlan(id,r,seq){const host=$('#bookingPlan');if(!host)return;host.innerHTML=ht`<div class="booking-invite"><div><p class="eyebrow">SIZNING JOYINGIZ TAYYOR</p><h2>Qaysi stolda o‘tirasiz?</h2><p>Zalni tepadan ko‘ring, qavat va o‘zingizga mos joyni tanlang.</p></div><button type="button" id="openBookingRoom" class="primary">Joy bron qilish <span aria-hidden="true">↗</span></button></div>`;$('#openBookingRoom').onclick=async()=>{closeBookingRoom();const dialog=document.createElement('dialog');dialog.id='bookingRoom';dialog.className='booking-room';dialog.innerHTML=ht`<header class="room-header"><button class="quiet" id="exitBookingRoom" type="button" aria-label="Bron oynasidan chiqish">← Chiqish</button><div><strong>${esc(r.name)}</strong><small>JOY BRON QILISH · TEPADAN KO‘RINISH</small></div></header><div class="room-body" id="bookingRoomContent"><p role="status">Zal ochilmoqda…</p></div>`;document.body.append(dialog);document.body.classList.add('booking-open');dialog.showModal();$('#exitBookingRoom').onclick=closeBookingRoom;dialog.addEventListener('cancel',e=>{e.preventDefault();closeBookingRoom()});dialog.addEventListener('click',e=>{if(e.target===dialog)closeBookingRoom()});try{await renderBookingRoom(id,r,seq,$('#bookingRoomContent'))}catch(e){if(dialog.isConnected)$('#bookingRoomContent').innerHTML=ht`<p>${esc(e.message)}</p><button type="button" class="quiet" id="retryRoom">Qayta urinish</button>`;if($('#retryRoom'))$('#retryRoom').onclick=()=>{closeBookingRoom();$('#openBookingRoom')?.click()}}};}
function bindFloorGestures(view,getFloor,count,change){let last=0,start=null;const shift=direction=>{if(Date.now()-last<650)return;const next=getFloor()+direction;if(next<1||next>count)return;last=Date.now();change(next)};view.addEventListener('wheel',e=>{if(count<2||Math.abs(e.deltaY)<Math.abs(e.deltaX)||Math.abs(e.deltaY)<8)return;const next=getFloor()+(e.deltaY>0?1:-1);if(next<1||next>count)return;e.preventDefault();shift(e.deltaY>0?1:-1)},{passive:false});view.addEventListener('touchstart',e=>{if(e.touches.length===1)start={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});view.addEventListener('touchmove',e=>{if(!start||e.touches.length!==1)return;const dx=e.touches[0].clientX-start.x,dy=e.touches[0].clientY-start.y;if(Math.abs(dy)>Math.abs(dx)*1.3&&Math.abs(dy)>30){const next=getFloor()+(dy<0?1:-1);if(next>=1&&next<=count)e.preventDefault()}},{passive:false});view.addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start.x,dy=e.changedTouches[0].clientY-start.y;start=null;if(Math.abs(dy)>50&&Math.abs(dy)>Math.abs(dx)*1.3)shift(dy<0?1:-1)},{passive:true});view.addEventListener('keydown',e=>{if(e.target!==view)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();shift(e.key==='ArrowDown'?1:-1)}})}
async function tableManager(r,seq){if(r.is_demo||r.id.startsWith('rf-demo-')){$('#tableEditor').innerHTML=ht`<div id="bookingPlan"></div>`;await bookingPlan(r.id,r,seq);return;}const host=$('#tableEditor');if(!host)return;let d;try{d=await api('/api/tables?edit=1&restaurantId='+encodeURIComponent(r.id))}catch(e){host.innerHTML=ht`<p>${esc(e.message)}</p>`;return}if(seq!==state.seq||$('#managedRestaurant')?.value!==r.id)return;let floor=Math.min(state.tableFloor||1,d.floors),drafts=[],busy=false;
 const draw=()=>{host.innerHTML=ht`<h2>Zalda stollar joyini belgilang</h2><p>1. Qavatni tanlang. 2. Har stol turadigan joyni bir marta bosing. 3. Nuqtalarning sig‘imini belgilang va saqlang.</p><p class="notice">${d.width&&d.length?ht`Zal: ${d.width} × ${d.length} m · ${Math.round(d.width*d.length*10)/10} m²`:t('Zal o‘lchamini yuqoridagi restoran sozlamasida kiriting.')} · ${d.tables.length+drafts.length} / ${d.total} ta joy belgilangan</p>${floorTabs(d.floors,floor)}<div class="floor-scroll"><div class="floor-plan point-plan" id="pointPlan" style="${hallStyle(d)}"><span class="plan-label">${floor}-QAVAT · BO‘SH JOYNI BOSING</span>${d.tables.filter(t=>t.floor===floor).map(t=>tableMarker(t)).join('')}${drafts.filter(t=>t.floor===floor).map(t=>tableMarker(t,'reserved',true)).join('')}</div></div><div class="point-toolbar"><button type="button" class="primary" id="savePoints" ${!drafts.length||busy?'disabled':''}>${busy?t('Saqlanmoqda…'):t('Belgilangan ')+drafts.length+t(' ta stolni saqlash')}</button><button type="button" class="quiet" id="editTableDetails">Saqlangan stollar: rasm va tavsif</button></div><p role="status" id="pointMessage"></p><div id="pointCapacities">${drafts.map(t=>ht`<div class="point-row"><strong>${t.number}-stol <small>${t.floor}-qavat</small></strong><label>SIG‘IMI<select data-point-seats="${t.id}" ${busy?'disabled':''}><option value="">Necha kishilik?</option>${Array.from({length:30},(_,i)=>ht`<option value="${i+1}" ${t.seats===i+1?'selected':''}>${i+1} kishi</option>`).join('')}</select></label><button type="button" class="quiet" data-remove-point="${t.id}" ${busy?'disabled':''}>Olib tashlash</button></div>`).join('')}</div>`;
 host.querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>{if(busy)return;floor=Number(b.dataset.floor);state.tableFloor=floor;draw()});$('#pointPlan').onclick=e=>{if(busy)return;const table=e.target.closest('[data-table]');if(table){if(String(table.dataset.table).startsWith('draft-')){host.querySelector('[data-point-seats="'+table.dataset.table+'"]').focus();host.querySelector('[data-point-seats="'+table.dataset.table+'"]').scrollIntoView({behavior:'smooth',block:'center'})}else notify(t('Bu stol saqlangan. “Rasm va tavsif” tugmasi bilan tahrirlang.'));return}const number=Array.from({length:d.total},(_,i)=>i+1).find(n=>![...d.tables,...drafts].some(t=>t.number===n));if(!number){notify(t('Barcha stol joylari belgilangan.'));return}const box=e.currentTarget.getBoundingClientRect(),x=Math.round(Math.max(8,Math.min(92,(e.clientX-box.left)/box.width*100))),y=Math.round(Math.max(10,Math.min(90,(e.clientY-box.top)/box.height*100)));if([...d.tables,...drafts].some(t=>t.floor===floor&&Math.abs(t.x-x)<9&&Math.abs(t.y-y)<13)){notify(t('Stollar bir-biriga juda yaqin. Biroz uzoqroq joyni bosing.'));return}drafts.push({id:'draft-'+number,number,floor,x,y,seats:null,shape:'rectangle',active:1});const scroll=$('#pointPlan').parentElement.scrollLeft;draw();$('#pointPlan').parentElement.scrollLeft=scroll;};
 host.querySelectorAll('[data-point-seats]').forEach(select=>select.onchange=()=>{const t=drafts.find(t=>t.id===select.dataset.pointSeats);t.seats=Number(select.value)||null;const marker=host.querySelector('[data-table="'+t.id+'"]');if(marker)marker.outerHTML=tableMarker(t,'reserved',true)});host.querySelectorAll('[data-remove-point]').forEach(b=>b.onclick=()=>{drafts=drafts.filter(t=>t.id!==b.dataset.removePoint);draw()});$('#editTableDetails').onclick=()=>{if(busy)return;if(drafts.length&&!confirm(t('Saqlanmagan nuqtalar bekor qilinadi. Davom etasizmi?')))return;detailedTableManager(r,seq)};$('#savePoints').onclick=async()=>{if(busy)return;if(drafts.some(t=>!t.seats)){$('#pointMessage').textContent=t('Har bir belgilangan stol necha kishilik ekanini tanlang.');host.querySelector('[data-point-seats="'+drafts.find(t=>!t.seats).id+'"]').focus();return}busy=true;draw();try{await api('/api/tables','POST',{action:'layout',restaurantId:r.id,points:drafts.map(({number,floor,x,y,seats,shape})=>({number,floor,x,y,seats,shape}))});notify(t('Stollar joylashuvi saqlandi. Rasm va tavsifni ham qo‘shishingiz mumkin.'));await tableManager(r,seq)}catch(e){busy=false;draw();$('#pointMessage').textContent=e.message}};};draw();}

// After a booking with a deposit: pick Click or Payme. Payment status comes back from the provider, not the browser.
function depositDialog(dep){const box=document.createElement('div');box.className='deposit-dialog';box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');const names={click:'Click',payme:'Payme'};box.innerHTML=ht`<div class="deposit-card"><h3>Depozitni to‘lang</h3><p>Bron saqlandi. Stol <b>${new Date(dep.expiresAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</b> gacha siz uchun ushlab turiladi.</p><p class="deposit-amount">${money(dep.amount)}</p><div class="deposit-actions">${Object.entries(dep.links).map(([k,url])=>ht`<a class="primary deposit-${k}" href="${esc(url)}" rel="noopener">${names[k]||esc(k)} orqali to‘lash</a>`).join('')}</div><button type="button" class="quiet" data-close>Keyinroq</button></div>`;document.body.appendChild(box);const card=box.querySelector('.deposit-card');window.RFMotion?.open(card,undefined,{backdrop:box});window.RFMotion?.swipe(card,()=>close());const close=()=>{const done=()=>{box.remove();location.hash='/bookings'};if(window.RFMotion)window.RFMotion.close(card).then(done);else done()};box.querySelector('[data-close]').onclick=close;box.addEventListener('keydown',e=>e.key==='Escape'&&close());box.querySelector('a,button')?.focus()}
